"""Independent known-answer generator for EXP-PFDR-bb0d26. Imports nothing from run.py,
check.py or the vendored curve code: plain dictionaries, integers and random."""
import json, random, sys, hashlib

def is_prime(n):
    if n < 2: return False
    i = 2
    while i * i <= n:
        if n % i == 0: return False
        i += 1
    return True

def pair_sums(X, p):
    # every unordered pair of distinct positions (u != v), sum mod p
    sums = {}
    for i in range(len(X)):
        for j in range(i + 1, len(X)):
            s = (X[i] + X[j]) % p
            sums[s] = sums.get(s, 0) + 1
    return sums

def CD(X, p):
    sums = pair_sums(X, p)
    C = 0
    for m in sums.values():
        C += m * (m - 1) // 2
    return C, len(sums)

def entry(name, p, X, note=""):
    assert len(set(X)) == len(X) and all(0 <= x < p for x in X)
    C, D = CD(X, p)
    return {"name": name, "p": p, "X": X, "n": len(X), "pairs": len(X) * (len(X) - 1) // 2, "C": C, "D": D, "note": note}

sets = []
