sets.append(entry("all-sums-distinct-powers-of-two", 65521, [2 ** k for k in range(15)], "Sidon set: C=0, D=n(n-1)/2"))
sets.append(entry("wrap-mod-101", 101, [0, 50, 51, 100, 7, 94]))
sets.append(entry("arithmetic-progression", 1009, [7 * k for k in range(10)], "AP: many coincidences"))
sets.append(entry("two-element", 13, [3, 9]))
sets.append(entry("full-field-small", 11, list(range(11))))
rng = random.Random(20261022)
primes = [q for q in range(1 << 11, 1 << 16) if is_prime(q)]
for t in range(30):
    bits = 12 + t % 5
    cand = [q for q in primes if q.bit_length() == bits]
    p = rng.choice(cand)
    n = rng.randrange(8, 61)
    X = rng.sample(range(p), n)
    sets.append(entry(f"random-{t}", p, X))
# forced coincidences: a + b = c + d planted in a random set
for t in range(4):
    p = rng.choice([q for q in primes if q.bit_length() == 13])
    X = rng.sample(range(p), 20)
    a, b, c = X[0], X[1], X[2]
    d = (a + b - c) % p
    if d not in X:
        X.append(d)
    sets.append(entry(f"forced-{t}", p, X, "contains a+b=c+d by construction"))

# label universe on a tiny curve, by explicit squares
def universe(p, a, b):
    squares = set((y * y) % p for y in range(1, p))
    return [x for x in range(p) if ((x ** 3 + a * x + b) % p) in squares and ((x ** 3 + a * x + b) % p) != 0]
uni = []
for (p, a, b) in ((1009, 3, 7), (10007, 5, 11), (12289, 2, 3)):
    uni.append({"p": p, "a": a, "b": b, "L": universe(p, a, b)})

# half-box geometry
def need(n): return -(-(102 * n) // 100) + 8
def T_of(r, n):
    T = 1
    while ((2 * T + 1) ** r - 1) // 2 < need(n): T += 1
    return T
halfbox = [{"r": r, "n": n, "need": need(n), "T": T_of(r, n), "size": ((2 * T_of(r, n) + 1) ** r - 1) // 2}
           for r in (1, 2, 3) for n in (256, 512, 1024, 2048, 4096)]
