def comb4(n): return n * (n - 1) * (n - 2) * (n - 3) // 24
cells = []
for bits in (20, 24, 28):
    for r in (1, 2, 3):
        for n in (256, 512, 1024, 2048, 4096):
            num = 1875 * 2 ** bits          # 3750 * 0.75 * 2^bits / 3 = 937.5 * 2^bits ; times 2 over 2
            den = 2 * comb4(n)              # => ceil(num / den) with num/den = 3750*0.75*2^bits/(3 C)
            raw = -(-num // den)
            cells.append({"cell": f"b{bits}-r{r}-n{n}", "bits": bits, "r": r, "n": n, "n_curves": min(2000, max(50, raw)), "raw": raw})
anch = {"b28-n256": next(c["n_curves"] for c in cells if c["bits"] == 28 and c["n"] == 256 and c["r"] == 1),
